module.exports = [
{"id":"baizhuoxia","name":"白灼虾","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/白灼虾/白灼虾.webp","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"519 大卡","time":"","servings":"1-2人份","description":"白灼虾是一道粤式经典快手菜，虾肉鲜甜弹嫩，原汁原味。虾本身富含优质蛋白和多种矿物质，搭配蘸料开胃不油腻。做法简单容错率高，对新手非常友好，从备料到出锅大约只需 15 分钟。","tags":["辣","新手友好"],"ingredients":[{"name":"葱 一根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜 一块","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"洋葱 一头","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜","amount":"5-8 瓣","optional":false,"amountValue":8,"amountUnit":"瓣"},{"name":"食用油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"料酒","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"酱油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"芝麻 一把","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香醋","amount":"10 ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"蚝油","amount":"10 ml","optional":false,"amountValue":10,"amountUnit":"ml"}],"steps":[{"text":"洋葱切小块，姜切片，平铺平底锅。","group":""},{"text":"活虾冲洗一下（去除虾线、剪刀减掉虾腿虾须子都是可选操作），控水，铺在平底锅的洋葱、姜片之上。","group":""},{"text":"锅内倒入料酒，盖上锅盖，中火 1 分钟，小火 5 分钟，关火 5 分钟。","group":""},{"text":"和上一步并行操作，制作蘸料：","group":""},{"text":"葱切成葱花、蒜切碎、倒入酱油、芝麻、香醋，搅拌之。","group":""},{"text":"油烧热，淋入蘸料。","group":""},{"text":"虾出锅，用干净的盘子装好。","group":""}],"tips":["技术细节：","开始不能大火、防止糊底。","如果锅盖有通气口、时间要相应调节一下（考虑增加 30 秒中火）。","蘸料其实也是可选的、也可以是纯的醋，大自然馈赠的鲜虾在没有水带走冲淡鲜甜的情况下口感味道都非常棒的。"]},
{"id":"bianyudundoufu","name":"鳊鱼炖豆腐","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/鳊鱼炖豆腐/鳊鱼炖豆腐.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"524 大卡","time":"","servings":"1-2人份","description":"鳊鱼炖豆腐是一道家常红烧菜，鱼肉鲜嫩入味，豆腐饱吸汤汁，咸鲜微辣。鳊鱼富含优质蛋白和不饱和脂肪酸，豆腐则提供植物蛋白和钙质，搭配起来营养均衡。制作难度适中，煎鱼时稍需耐心防粘，整体步骤清晰，新手也能尝试。从备料到完成约需 40 分钟。","tags":["辣","汤"],"ingredients":[{"name":"鳊鱼：550 克","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"老豆腐：400 克","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜：5 片","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"葱：半根（50 克）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜：4 个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽：2ml（不太喜欢重口的可以不放）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"桂皮：1 块","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"冰糖：5 块","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"干辣椒：4-6 个（根据个人口味选择）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒：5ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽：4ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐：5-8 克（根据个人口味选择）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角：1 个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香叶：1-3 片","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油：10ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"热水：400 克","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"鳊鱼改刀，放上姜片和料酒腌制 5-10 分钟","group":""},{"text":"老豆腐切块后放入水中备用","group":""},{"text":"锅中加油，可以放点盐在锅里，防止煎鱼的时候粘锅，把腌制的鱼用厨房纸擦干水分，把鱼放到锅中，两面都煎一下","group":""},{"text":"等两面都煎好时，把鱼推向锅边一点，留点空间放入葱姜蒜，干辣椒，香叶，八角炒出味道","group":""},{"text":"炒出佐料香味后，加入料酒，生抽，老抽，冰糖，桂皮，倒入热水，水量和鱼平齐或者少点","group":""},{"text":"大火烧开后，放入老豆腐，豆腐贴在锅边，加入食盐，转小火","group":""},{"text":"小火烧 10-15 分钟，然后大火收点汁，即可出锅","group":""}],"tips":["鱼的两面，各煎 2-4 分钟即可","煎鱼的时候全程中小火","最后出锅时，加入一些切碎的大蒜，味道会更好"]},
{"id":"chengbaodan","name":"蛏抱蛋","category":"水产","categoryKey":"aquatic","emoji":"🥚","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/蛏抱蛋/1.jpeg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"1229 大卡","time":"","servings":"1-2人份","description":"蛏抱蛋是福建福州一带的传统家常菜，蛏肉裹着蛋液煎得外酥里嫩，带着洋葱和生抽的咸鲜香气。蛏子富含优质蛋白和锌、铁等微量元素，与鸡蛋搭配营养均衡。制作难度适中，需掌握煎炸火候但步骤不繁琐，预计 大约 30 分钟就能端上餐桌。","tags":[],"ingredients":[{"name":"蛏子","amount":"200 g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"鸡蛋","amount":"2 个","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"食用油","amount":"100 ml","optional":false,"amountValue":100,"amountUnit":"ml"},{"name":"洋葱","amount":"0.25 个","optional":false,"amountValue":0.25,"amountUnit":"个"},{"name":"淀粉","amount":"20 g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"生抽","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"鸡精","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"料酒","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"烧开水，将蛏子放入水中，水煮 2 分钟后，捞上来去壳，放入大碗","group":""},{"text":"往大碗中加入洋葱、生抽、料酒、鸡精、生粉后，充分搅拌","group":""},{"text":"往大碗中打入 2 个 鸡蛋，继续搅拌","group":""},{"text":"起锅烧油，倒入碗中蛏子，煎炸至单面金黄后，翻面继续煎炸","group":""}],"tips":["更多情况下，福州当地会选用马蹄（解腻）和马铃薯（洗油），因为疫情期间买不到，所以选用了凤梨","闽菜以甜为主，如果吃不惯的可以放弃白糖","可以通过勺子敲打瘦肉块，听到声响来判断是否炸透瘦肉"]},
{"id":"congshaohaishen","name":"葱烧海参","category":"水产","categoryKey":"aquatic","emoji":"🌿","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/葱烧海参/葱烧海参.jpeg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"299 大卡","time":"","servings":"1-2人份","description":"这是一道经典的鲁菜家常烧制海味，以浓郁的葱香和软糯入味的海参为特色，汤汁稠亮咸鲜回甜。海参富含胶原蛋白与多种微量元素，对滋养身体很有益处。整体烹饪难度不高，但需提前花时间将干海参充分泡发，实际烧制过程约三十分钟即可完成，新手只要按步骤操作也容易成功。","tags":[],"ingredients":[{"name":"泡发好的海参（北极参）","amount":"4 个","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"大葱葱白","amount":"1 根大葱的葱白即可","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"食用油","amount":"20-25ml","optional":false,"amountValue":25,"amountUnit":"ml"},{"name":"蚝油","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"生抽","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"白糖","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"淀粉","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"葱白切成 1cm 的段，备用。","group":""},{"text":"海参切成 1cm 的段，备用。","group":""},{"text":"准备一个空碗，倒入 20g 蚝油， 10g 生抽， 2g 白糖，搅拌均匀。","group":""},{"text":"另一个空碗倒入淀粉，水，制备水淀粉，勾芡用。","group":""},{"text":"热锅，锅内放入 20ml - 25ml 食用油。等待 10 秒让油温升高。","group":""},{"text":"放入葱白，调*小火*，注意不要让葱白变焦。大概煎 3-5 分钟即可。","group":""},{"text":"用筷子夹出葱白，放入盘中备用。","group":""},{"text":"倒入调好的料汁，炒香，**等待 1 - 2 分钟** 。","group":""},{"text":"放入切好的海参，翻炒 1 分钟","group":""},{"text":"加入 100 ml 的水， 中小火， **等待 5 分钟**","group":""},{"text":"等待锅中汤汁快干的时候，加入水淀粉，加入前面取出的葱白","group":""},{"text":"在外观*呈粘稠状态*后关火，盛盘","group":""}],"tips":["操作时，需要注意观察锅中的水量，如快见底的时候就直接接入水淀粉即可。"]},
{"id":"congyouguiyu","name":"葱油桂鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/葱油桂鱼/葱油桂鱼.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"311 大卡","time":"45分钟","servings":"1人份","description":"葱油桂鱼是一道葱香浓郁、鱼肉鲜嫩的家常蒸菜，属于中式清淡口味，适合各地人群。桂鱼富含优质蛋白和不饱和脂肪酸，经过精细去腥处理，保留了鱼肉的鲜美与营养。做法对新手十分友好，容错性高，只要按步骤操作，基本零失败。从备料到出锅，全程大约需要 45 分钟。","tags":["辣","蒸","进阶挑战"],"ingredients":[{"name":"桂鱼","amount":"1 斤(500g)","optional":false,"amountValue":1,"amountUnit":"斤"},{"name":"小葱","amount":"1 根（长度为 30cm）","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"小米辣","amount":"2 个","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"姜","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"料酒","amount":"25g","optional":false,"amountValue":25,"amountUnit":"g"},{"name":"植物油","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"盐","amount":"8g","optional":false,"amountValue":8,"amountUnit":"g"},{"name":"蒸鱼豉油","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"清水","amount":"5L","optional":false,"amountValue":5000,"amountUnit":"ml"}],"steps":[{"text":"去菜市场买已经处理好的鱼（自己处理的话最好不要内脏），将鱼身表面的所有鳞片刮干净","group":""},{"text":"用厨房用纸将鱼肚子里的贴骨血和黑膜擦干净（帖骨血会影响口感，黑膜是鱼腥味的来源）","group":""},{"text":"用菜刀在鱼身表面来回刮几次，将鱼身的黏液刮掉，进一步去除腥味，然后用清水将鱼内外冲洗干净","group":""},{"text":"将鱼平放在砧板，使用厨房纸将鱼内外的水分擦干，然后鱼头朝左，尾朝右，从鱼鳃边开始，每隔 3cm 纵向划一刀，深度达到鱼的脊椎骨即可，另一面使用同样的处理方式","group":""},{"text":"将鱼平放在盆中，确保盘中没有多余水分","group":""},{"text":"取一块 50g 姜（鸡蛋大小），用削皮刀把表面的皮去除并洗干净，然后切成厚度为 3mm 的姜片","group":""},{"text":"将小米辣洗干净、去蒂，切成厚度为 2mm 的小圆片（或切成 1mm 宽度的丝状）","group":""},{"text":"将小葱洗干净，去除根须，切成 3cm 的小段，稍微粗一点的小葱，可以沿着小葱生长的方向沿中间劈开","group":""},{"text":"加入 8g 盐，25g 料酒到盆中，带上一次性手套，然后对鱼进行全身按摩 1 分钟，确保鱼身每个部位都均匀涂抹了盐和料酒","group":""},{"text":"按摩好鱼后，在鱼身的每一个刀口中塞入一片姜片，鱼肚子中放入 3 片姜片，腌制 10 分钟（建议不要腌制太久，否则鱼的鲜度降低）","group":""},{"text":"在鱼腌制期间，在蒸锅中加入 5L 清水，烧开后，在蒸锅上放上蒸笼","group":""},{"text":"鱼腌制好后，会析出水分，将多余水分和腌制用料酒、姜片倒掉，用清水冲洗干净鱼身和鱼肚，用厨房纸擦干鱼身和鱼肚","group":""},{"text":"将鱼平放在蒸鱼盘中，重新在鱼身、鱼肚刀口处塞入姜片","group":""},{"text":"然后将蒸鱼盘放入蒸笼中，盖上盖子，中火蒸 20 分钟","group":""},{"text":"期间水蒸气会附着整个鱼和盘子上，凝结后形成鱼汤，出锅后千万不要倒掉这个汤，这个汤汁是鲜味精华","group":""},{"text":"用防烫夹将蒸鱼盘夹出，在鱼身和鱼周围淋上 10g 蒸鱼豉油","group":""},{"text":"然后在鱼身和周围均匀撒上小葱段和小米辣","group":""},{"text":"在铁锅中倒入 15g 植物油，用中小火慢熬 5 分钟，不要用大火，否则油会挥发很快","group":""},{"text":"将出锅后的热油均匀地慢慢地淋在鱼身上，鲜掉眉毛的葱油桂鱼就出炉啦！","group":""}],"tips":["经过若干次测试，成功率 100%，这道菜容错性很高，无论是什么省份、什么口味的人都能兼容。另外，本套教程虽然叫葱油桂鱼的做法，但原料本身不仅限于桂鱼，可以用鲈鱼、多宝鱼等海鱼代替（淡水鱼本身寄生虫会比海鱼多一点，不建议使用淡水鱼，淡水鱼的做法请参考《红烧鱼》等教程），耦合性低、可扩展性强。"]},
{"id":"ganjianagentinghongxia","name":"干煎阿根廷红虾","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/干煎阿根廷红虾/干煎阿根廷红虾.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"309 大卡","time":"","servings":"1人份","description":"一道鲜美诱人的海鲜快手菜，煎制后的阿根廷红虾肉质白嫩，口感鲜甜浓郁，虾壳酥香。富含碘、磷和虾青素等微量元素，有助于增强免疫力、保护心脏并降低胆固醇。难度适中，需要掌握火候和翻面技巧，但步骤清晰，新手按操作来也能成功。预计 大约 20 分钟即可完成。","tags":[],"ingredients":[{"name":"阿根廷红虾","amount":"2-3 只","optional":false,"amountValue":3,"amountUnit":"只"},{"name":"海盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"黑胡椒（研磨装）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"白葡萄酒","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"生抽","amount":"1ml","optional":false,"amountValue":1,"amountUnit":"ml"},{"name":"香菜","amount":"3 片","optional":false,"amountValue":3,"amountUnit":"片"},{"name":"柠檬","amount":"1 片","optional":false,"amountValue":1,"amountUnit":"片"},{"name":"洋葱","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"生姜","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"大蒜","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"}],"steps":[{"text":"阿根廷红虾解冻，最好是提前 1 天从速冻取出放到冷藏里自然解冻，能更好保持风味和口感。可买已经开背去虾线的，节省了不少时间","group":""},{"text":"解冻好的红虾洗净擦干备用，注意这里一定要沥干水分，赶时间可以用厨房用纸吸干水分","group":""},{"text":"生姜切片，洋葱切小方块，香菜洗干净后，叶茎分离，把香菜叶切碎，大蒜压碎切成小块碎末","group":""},{"text":"大火热锅，热锅后倒入两调羹橄榄油，等油温升高后，放入生姜片，洋葱块和香菜茎煸炒","group":""},{"text":"约 1 分钟后取出生姜，洋葱和香菜茎，弃用","group":""},{"text":"调中大火，放入红虾开始煎，注意所有虾需要单面都完整接触平底锅，煎约 2 分钟，同时给每只虾刷上一层油","group":""},{"text":"待底面虾壳有微微焦黄时翻面，并撒入大蒜碎末，轻微晃动平底锅使得受热均匀","group":""},{"text":"约 1 分钟后添加 20ml 白葡萄酒","group":""},{"text":"再煎 1 分钟后调中小火，均匀撒上一层盐和黑胡椒","group":""},{"text":"给每只虾滴上一滴生抽","group":""},{"text":"撒上香菜叶，装盘","group":""},{"text":"切好柠檬片，摆放到盘边即可","group":""}],"tips":["柠檬可提升虾的口感，但偏酸，可以根据喜好添加，也可以不用","趁热吃"]},
{"id":"hongshaoliyu","name":"红烧鲤鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"1051 大卡","time":"","servings":"2人份","description":"红烧鲤鱼是一道家常鲁菜，鱼肉先炸后炖，外皮微韧，肉质鲜嫩，咸甜酱香中透着五花肉的醇厚，汤汁浓稠下饭。富含优质蛋白和钙、磷等矿物质，有助滋补。处理炸鱼和调味配比稍需耐心，但步骤清晰，新手跟着做也能完成。从备料到出锅预计 大约 1 小时。","tags":["辣","进阶挑战"],"ingredients":[{"name":"鲤鱼 （大约","amount":"2 斤）","optional":false,"amountValue":2,"amountUnit":"斤"},{"name":"五花肉","amount":"100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"大葱","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"姜","amount":"80g","optional":false,"amountValue":80,"amountUnit":"g"},{"name":"蒜瓣","amount":"3-4 个","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"干辣椒两个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"白糖","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"}],"steps":[{"text":"葱、姜、蒜、干辣椒分别清洗干净。","group":""},{"text":"葱白处切段，每段长度约 4cm，再将每段劈为四瓣。","group":""},{"text":"姜切片，每片厚度约 3mm。","group":""},{"text":"一个大蒜拍碎切末，其余蒜切为二瓣。","group":""},{"text":"干辣椒切四段。","group":""},{"text":"五花肉切片，约 4cm*4cm。","group":""},{"text":"清洗鱼。","group":""},{"text":"鱼背肉厚处拉几道斜口，方便入味","group":""},{"text":"锅里多倒点油，烧至 7 成热（刚刚开始冒烟），下入鱼炸 1 分钟至鱼皮稍稍变硬捞出备用（注意不要一下锅就拨弄鱼，等炸一会再拨弄、翻面），炸鱼的油倒出，锅里留一点底油","group":""},{"text":"将锅里底油烧热，下入五花肉，煸出香味。","group":""},{"text":"放入干辣椒、葱、姜、蒜瓣，翻炒 1 分钟。","group":""},{"text":"将炸好的鱼倒入锅中。","group":""},{"text":"沿锅边倒入","group":""},{"text":"50ml 料酒","group":""},{"text":"50ml 陈醋","group":""},{"text":"50ml 味极鲜","group":""},{"text":"20ml 老抽调色","group":""},{"text":"5ml 蚝油提鲜","group":""},{"text":"5g 匙盐","group":""},{"text":"50g 白糖","group":""},{"text":"清水没过鱼面。","group":""},{"text":"调至中火，将水烧开。","group":""},{"text":"调至小火，慢焖入味。","group":""},{"text":"15 分钟 后，打开锅盖，挑出锅里的葱、姜、蒜、干辣椒。","group":""},{"text":"调至大火收汁，汤汁剩余 1/4 时，撒点蒜末，关火盛出。","group":""},{"text":"红烧鲤鱼出锅！","group":""}],"tips":["基于下列原因，需要在红烧鲤鱼中添加五花肉：","五花肉煸炒的时候会出猪油，相比较于植物油，动物油脂更香。","煸炒至金黄的五花肉炖煮过后吃起来也很香的，相当于配菜。","鱼类本身脂肪含量少，所以香味欠缺，着重的是肉质的口感。所以一般做鱼类菜都建议用猪油，想要一锅奶白香醇的鱼汤。猪油是最好的选择~"]},
{"id":"hongshaoyu","name":"红烧鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"570 大卡","time":"40分钟","servings":"1人份","description":"红烧鱼是一道家常风味浓郁的经典菜，咸鲜微甜，鱼肉嫩滑入味，属于大众喜爱的中式烧菜。鱼肉富含优质蛋白和不饱和脂肪酸，营养易吸收。制作时需要处理生鱼和油煎，步骤稍多，对新手有一定挑战，但跟着菜谱操作也能成功。从备料到出锅，大约需要 40 分钟。","tags":["辣","进阶挑战"],"ingredients":[{"name":"鱼 建议新手以一条中等大小的鲫鱼上手，提前划好花刀，方便成熟（不然鱼背上容易夹生）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜丝，以正常老姜切","amount":"2-3 片，然后片丝即可","optional":false,"amountValue":3,"amountUnit":"片"},{"name":"蒜瓣","amount":"3-4 个，拍碎或者切碎或者切片","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"干辣椒（依照个人口味）2-3 个，切碎","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香菜按照个人口味","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐","amount":"10g，如果辣椒辣度高，建议多一点","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"醋","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"酱油","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"白砂糖","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"葱","amount":"1-2 根，正常就撒葱花","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"小米椒","amount":"1-2，不放也可以，过来人的经验，最多放 2 个，不然辣度过高要菊花残。","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"味精，看个人口味，不要放多，5g 即可。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"蚝油，5g 即可，和味精一个道理","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"姜蒜准备好，切碎","group":"原材料准备"},{"text":"干辣椒切碎，和姜蒜一起","group":"原材料准备"},{"text":"加入 30-50ml 油，等待锅热...","group":"最终步骤"},{"text":"放入**擦干水分的鱼**（不想被热油溅一身的话），然后晃动锅，用热油煎鱼，注意这过程一定要小火","group":"最终步骤"},{"text":"将鱼翻面，重复上面油煎过程","group":"最终步骤"},{"text":"放入姜蒜辣椒，翻炒出香味","group":"最终步骤"},{"text":"倒入料酒，稍微多一点，此过程注意安全，会起大量油烟","group":"最终步骤"},{"text":"倒入醋（喜欢醋可以多放一点）","group":"最终步骤"},{"text":"然后放入白砂糖，酱油（老抽)","group":"最终步骤"},{"text":"加入冷水，以刚好淹没鱼身为宜，然后调成中火，盖上锅盖，大概 1 分钟后将鱼翻身，继续盖上锅盖","group":"最终步骤"},{"text":"3-4 分钟后，加入盐、小米椒、蚝油（味精、鸡精等），然后继续盖上锅盖，后续继续要翻身","group":"最终步骤"},{"text":"当锅内汤汁收汁到鱼的脊背线上的鱼鳍下面一点点的时候（或者汤汁不多的时候），转小火，加入香菜，葱花，然后盖上锅盖 20 秒，关火","group":"最终步骤"},{"text":"起锅","group":"最终步骤"}],"tips":[]},
{"id":"hongshaoyutou","name":"红烧鱼头","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"333 大卡","time":"","servings":"2人份","description":"红烧鱼头是一道经典的家常烧菜，鱼头胶质丰富，肉质滑嫩，汤汁咸鲜微辣，十分下饭。鱼头富含优质蛋白、卵磷脂和不饱和脂肪酸，对滋养皮肤和大脑有益。由于需要处理生鱼和剁骨，难度稍高，不建议完全零基础的新手独自操作，全程制作（含腌制）约需 2–2.5 小时。","tags":["辣","进阶挑战"],"ingredients":[{"name":"鱼头一个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"大葱","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"姜","amount":"80g","optional":false,"amountValue":80,"amountUnit":"g"},{"name":"蒜瓣","amount":"3-4 个","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"美人椒","amount":"1/4 个","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"香菜","amount":"4 棵","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角两个，干辣椒五个","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"葱、姜、蒜、香菜、美人椒分别清洗干净。","group":"原材料准备"},{"text":"干辣椒与八角稍微冲洗即可。","group":"原材料准备"},{"text":"大葱切两半。后半段大葱（葱白处）切段，每段长度约 4cm。前半段（葱叶处）先切段，再将每段劈为四瓣。","group":"原材料准备"},{"text":"姜切片，每片厚度约 3mm。","group":"原材料准备"},{"text":"大蒜拍碎。","group":"原材料准备"},{"text":"拿出两棵香菜去根，切为 1.5cm 香菜碎。","group":"原材料准备"},{"text":"将美人椒切为厚度为 3mm 的辣椒圈。","group":"原材料准备"},{"text":"干辣椒切四段。","group":"原材料准备"},{"text":"注：下文所述的鱼身是购买鱼头时所附带的鱼肉。","group":"腌制鱼头"},{"text":"将鱼头去鳞，清洗鱼头处未被清理干净的内脏。","group":"腌制鱼头"},{"text":"剁去鱼鳍、清理鱼鳃。","group":"腌制鱼头"},{"text":"将鱼头下巴与鱼身连接的地方剁开，鱼身剁块，鱼头剁成四/六瓣。","group":"腌制鱼头"},{"text":"注：鱼的处理很难用文字完全表述，可以搜索鱼头处理相关视频。","group":"腌制鱼头"},{"text":"将剁好的鱼头进行清洗，最好洗掉鱼块上滞留的血水。","group":"腌制鱼头"},{"text":"将清洗好的鱼块放入盆中，加入 5g 盐、10g 生抽、10g 料酒。放入葱（前半段切碎的那个）、1/3 姜片。将其拌匀，静置 1-2 小时。","group":"腌制鱼头"},{"text":"加入 30ml 油，等待锅热...","group":"最终步骤"},{"text":"油热，将锅关至小火","group":"最终步骤"},{"text":"如果不明白为何要这样做，请查看[学习炒与煎](../../tips/learn/学习炒与煎.md)中的翻炒辅料。","group":"最终步骤"},{"text":"放入姜片，慢慢翻炒，以姜片中的大部分汁水被炒出，以金黄色为准。","group":"最终步骤"},{"text":"放入葱段，翻炒至葱段略显发白。","group":"最终步骤"},{"text":"放入蒜碎、八角、干辣椒，翻炒 5 秒。","group":"最终步骤"},{"text":"将腌制好的鱼头倒入锅中，翻炒 2-3 分钟。","group":"最终步骤"},{"text":"倒入 500ml 清水，加入 2g 盐、3g 鸡精、5g 生抽、3g 老抽、5g 料酒、2g 黑胡椒粉、3g 陈醋。","group":"最终步骤"},{"text":"将两棵香菜放入锅中，盖上锅盖。","group":"最终步骤"},{"text":"调至大火，将水烧开。","group":"最终步骤"},{"text":"调至中火，慢焖入味。","group":"最终步骤"},{"text":"当汤汁减少一半时，打开锅盖。","group":"最终步骤"},{"text":"调至大火收汁，汤汁剩余 1/3 时，关火盛至小盆中。","group":"最终步骤"},{"text":"注：将锅中的汤汁均匀淋到鱼头上，盛盘时可以将锅中煮的香菜放入小盆底部，这样能让成品菜好看又好吃。","group":"最终步骤"},{"text":"将香菜放至已经盛出的鱼头上，把切好的美人椒圈放在香菜之上。","group":"最终步骤"},{"text":"色香味俱全的红烧鱼头出炉！","group":"最终步骤"}],"tips":[]},
{"id":"huangyoujianxia","name":"黄油煎虾","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/黄油煎虾/黄油煎虾.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"741 大卡","time":"","servings":"1-2人份","description":"黄油煎虾是一道风味浓郁、虾肉鲜嫩弹牙的家常海鲜菜。鲜虾富含优质蛋白和钙、锌等矿物质，搭配黄油增添了奶香与能量。制作相对简单，只需耐心处理活虾，新手也能顺利上手，总耗时约一小时。","tags":[],"ingredients":[{"name":"鲜虾","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"黄油","amount":"7g","optional":false,"amountValue":7,"amountUnit":"g"},{"name":"黑胡椒粒 大概","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"食用油","amount":"45ml","optional":false,"amountValue":45,"amountUnit":"ml"},{"name":"生抽","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"米酒","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"白糖","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"盐","amount":"2.5ml","optional":false,"amountValue":2.5,"amountUnit":"ml"}],"steps":[{"text":"鲜虾摘除头部，顺带扯出虾线（这步处理不好可在下一步开背时取出虾线），使用剪刀剪开或菜刀片开虾背，沥干水分备用","group":""},{"text":"调制酱汁：小碗放入上述量的全部生抽、米酒、白糖、盐搅匀备用","group":""},{"text":"中大火热锅，热锅内放入食用油，等待 10 秒让油温升高","group":""},{"text":"虾全部放入锅中，开始瓶磨黑胡椒，均匀地撒在虾上翻炒","group":""},{"text":"虾变色后加入黄油，黄油完全融化后倒入调制酱汁，继续翻炒","group":""},{"text":"大火翻炒 15 秒收汁即可装盘","group":""}],"tips":["虾开背才更好入味，不过处理时切记切记小心用刀，新手容易伤到手","冯小厨的菜谱"]},
{"id":"jiangdunxie","name":"酱炖蟹","category":"水产","categoryKey":"aquatic","emoji":"🦀","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"468 大卡","time":"","servings":"1-2人份","description":"这道菜是浙江平湖地区的秋日限定咸鲜风味，蟹黄绵润裹着酱香，蟹肉清甜，汤汁拌饭一绝。富含优质蛋白和微量元素。难度适中，适合有基础的新手，从准备到出锅大约 30 分钟。","tags":["辣","汤"],"ingredients":[{"name":"螃蟹","amount":"500 g（约 3-4 只中等河蟹）","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"豆瓣酱","amount":"30-50 g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"冰糖","amount":"0-15 g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"老抽","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"菜油","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"番茄酱","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"料酒","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"老姜","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"葱","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"鸡蛋","amount":"1 个（约 50 g）","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"猪肉末","amount":"50 g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"水","amount":"500 mL","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"把螃蟹刷洗干净，然后在砧板上对半劈开","group":""},{"text":"锅里下菜油，放入姜末和豆瓣酱爆香，加入冰糖炒化，直到冒小气泡就盛出","group":""},{"text":"在盘子里铺上一层酱，然后把切好的螃蟹切开面朝下，整齐排放在酱上","group":""},{"text":"放点葱段和姜片，建议敲个鸡蛋或在盘底铺肉末","group":""},{"text":"上锅蒸 10-12 分钟","group":""}],"tips":["咸口放 50 g 豆瓣酱，甜口减少豆瓣酱的用量并加入冰糖和番茄酱","出锅后再撒上一点葱花会更香也更好看","参考资料：秋风起，平湖这道美味很下饭_潮新闻官网"]},
{"id":"jiemohuangyouluoshixia","name":"芥末黄油罗氏虾","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/芥末黄油罗氏虾/芥末黄油罗氏虾.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"637 大卡","time":"30分钟","servings":"1人份","description":"这道菜以黄油与芥末的奇妙搭配为亮点，虾肉紧实弹嫩，酱汁浓郁辛香，是一道新派海鲜菜肴。虾肉富含优质蛋白和多种微量元素，营养均衡。制作难度适中，只要提前备好料、控制火候，新手也能成功。从处理活虾到出锅，大约需要 30 分钟。","tags":[],"ingredients":[{"name":"罗氏虾","amount":"1 斤多  广东市场价大概 40~45 一斤","optional":false,"amountValue":1,"amountUnit":"斤"},{"name":"黄油 约","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"芥末","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"白糖","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"生抽","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"蚝油","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"料酒、朗姆酒或啤酒","amount":"15g 到 30g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"香菜","amount":"5 条 切段","optional":false,"amountValue":5,"amountUnit":"条"},{"name":"蒜","amount":"5 颗 剁成蒜蓉","optional":false,"amountValue":5,"amountUnit":"颗"}],"steps":[{"text":"将罗氏虾剪掉头尾尖刺、触须和脚，剪刀把虾身开背，去除虾线。","group":""},{"text":"提前搅拌好芥末酱汁：酱油、蚝油、芥末、盐、糖，搅拌均匀！","group":""},{"text":"洗好香菜，切段备用。","group":""},{"text":"罗氏虾沥干水，锅中加入油，直接放入罗氏虾，中火，外表煎至金黄，捞出。","group":""},{"text":"下入蒜蓉，大火，利用煎虾剩下的油继续煎炒蒜蓉，等到锅中白雾冒出，蒜蓉已经煎出香味，下虾和黄油，让虾充分吸收黄油香味","group":""},{"text":"下入调好的酱汁，继续大火煮沸，翻炒虾，至酱汁收汁，加入酒（料酒、啤酒可以放 30g，朗姆酒味道浓郁放 15g 即可。）","group":""},{"text":"在等酱汁稍微收汁，加入香菜翻炒两下，即可出锅。","group":""}],"tips":["酱汁提前调配好，黄油提前备好，防止中间备料耗时。","蒜蓉切记要等虾煎好后捞出再下，防止煎炒过久变黑，发苦。","如果不太能接受芥末就放少点，能接受就放多点，如果放多了，煮久一会儿，芥末味也会散去。"]},
{"id":"kalichaoxie","name":"咖喱炒蟹","category":"水产","categoryKey":"aquatic","emoji":"🦀","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"815 大卡","time":"","servings":"1人份","description":"这是一道融合泰式风味的家常海鲜菜，浓郁咖喱包裹着爆满的蟹肉，带有蟹黄香气和椰浆的顺滑口感。螃蟹富含优质蛋白和多种微量元素，有助于补充体力。制作工序清晰，只需注意封煎蟹黄和最后关火翻炒酱汁，对有一定下厨经验的人比较友好，一般从备料到出锅约需 30 分钟。","tags":["进阶挑战"],"ingredients":[{"name":"肉蟹","amount":"1 只（大约 300g） * 份数","optional":false,"amountValue":1,"amountUnit":"只"},{"name":"咖喱块","amount":"15g（一小块）*份数","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"椰浆","amount":"100ml*份数","optional":false,"amountValue":100,"amountUnit":"ml"},{"name":"鸡蛋","amount":"1 个 *份数","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"洋葱","amount":"200g *份数","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"大蒜","amount":"5 瓣 *份数","optional":false,"amountValue":5,"amountUnit":"瓣"}],"steps":[{"text":"肉蟹掀盖后对半砍开，蟹钳用刀背轻轻拍裂，切口和蟹钳蘸一下生粉，不要太多。撒 5g 生粉到蟹盖中，盖住蟹黄，备用","group":""},{"text":"洋葱切成洋葱碎，备用","group":""},{"text":"大蒜切碎，备用","group":""},{"text":"烧一壶开水，备用","group":""},{"text":"起锅烧油，倒入约 20ml 食用油，等待 10 秒让油温升高","group":""},{"text":"将螃蟹切口朝下，轻轻放入锅中，煎 20 秒，这一步主要是封住蟹黄，蟹肉。然后翻面，每面煎 10 秒。煎完将螃蟹取出备用","group":""},{"text":"将螃蟹盖放入锅中，使用勺子舀起锅中热油泼到蟹盖中，煎封住蟹盖中的蟹黄，煎 20 秒后取出备用","group":""},{"text":"不用刷锅，再倒入 10ml 食用油，大火让油温升高至轻微冒烟，将大蒜末，洋葱碎倒入，炒 10 秒钟","group":""},{"text":"将咖喱块放入锅中炒化（10 秒），放入煎好的螃蟹，翻炒均匀","group":""},{"text":"倒入开水 300ml，焖煮 3 分钟。","group":""},{"text":"焖煮完后，倒入椰浆和蛋清，关火，关火后不断翻炒，一直到酱汁变浓稠。","group":""},{"text":"出锅","group":""}],"tips":["做法参考：十几年澳门厨房佬教学挂汁的咖喱蟹怎么做"]},
{"id":"kaoyu","name":"烤鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/混合烤鱼/烤鱼.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"2152 大卡","time":"","servings":"1-2人份","description":"这道川味烤鱼麻辣鲜香，鱼肉外焦里嫩，配菜吸饱汤汁后格外下饭。草鱼富含优质蛋白，搭配多种蔬菜，营养均衡。做法看似复杂，但跟着步骤走其实不难，适合想挑战硬菜的新手。从备料到上桌大约需要一小时。","tags":["辣","烤","进阶挑战"],"ingredients":[{"name":"草鱼 大约三斤","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"大葱 半根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油","amount":"20ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"料酒","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"食用盐","amount":"5-10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"白胡椒粉","amount":"5g-10g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"桂皮 一小片","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角 两个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"大蒜粒 八个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香叶 两张","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"青花椒 一小把","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"干辣椒段","amount":"10 个","optional":false,"amountValue":10,"amountUnit":"个"},{"name":"灯笼椒","amount":"4 个","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"芹菜段 两根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"洋葱 半个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"千张 一张","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"草鱼（一般 3 斤 ）从背部切开，两面沿着鱼的背部往下划几刀，不要划到鱼肚皮，不然不易定型","group":""},{"text":"可以用热水浇在鱼身上洗去粘液或者用刷子在流动水龙头下面不停的刷洗，直到摸着没有黏糊糊的手感。","group":""},{"text":"把鱼放到容器中，加入料酒，10g 白胡椒粉，5g 食盐抹匀腌制二十分钟入味。","group":""},{"text":"把半根大葱切成一块一块，大蒜粒中间切开，和八角香叶桂皮放在一个容器中","group":""},{"text":"干辣椒段中间一分为二切开并和灯笼椒装在一个容器中","group":""},{"text":"芹菜切小段","group":""},{"text":"豆芽焯水","group":""},{"text":"千张焯水切成丝","group":""},{"text":"洋葱切成丝。","group":""},{"text":"烤制鱼","group":""},{"text":"家里有烤箱的可以在烤盘刷上底油，鱼皮朝下，直到烤制两面金黄，然后撒上孜然粉","group":""},{"text":"如果没有烤箱，可以热锅热油，锅的两边撒上 2g 食盐，下入草鱼开始煎，刚下入的时候不要着急翻动，等一面定型后再翻面，煎制两面金黄，撒上孜然粉，出锅装在盘子里准备。","group":""},{"text":"锅中撒上 20ml 食用油，等到油热后，把大葱大蒜八角香叶倒入炒香","group":""},{"text":"加上一包火锅底料的一半和 15-20g 豆瓣酱，炒出红油","group":""},{"text":"加入 5g 白糖，10g 食盐，5ml 生抽调味，倒入和食材齐平的清水煮开","group":""},{"text":"依次下入芹菜段，豆芽，千张丝，不用煮熟，稍微烫一下后铺上洋葱丝，放上烤鱼","group":""},{"text":"加入干辣椒，灯笼椒，青花椒","group":""},{"text":"另一个锅烧油，油热后浇在刚加入的辣椒上面激发出香味","group":""},{"text":"最后撒上熟花生米，葱花，白芝麻，香菜","group":""},{"text":"煮 5-6 分钟，美味即成。","group":""}],"tips":["技术总结：上述","这道菜的食盐，胡椒粉，孜然粉，食用油，生抽，白糖等的使用量，根据个人口味和食材比例做决定，并不需要严格按照上述分量来做。"]},
{"id":"liyudunbaicai","name":"鲤鱼炖白菜","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/鲤鱼炖白菜/鲤鱼炖白菜.jpeg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"792 大卡","time":"40分钟","servings":"1-2人份","description":"鲤鱼炖白菜是一道鲜香浓郁的家常炖菜，鱼肉软嫩入味，白菜清甜吸汁，属于典型的北方风味。鲤鱼富含优质蛋白和不饱和脂肪酸，搭配白菜提供膳食纤维和维生素，营养均衡。制作过程需要煎鱼和炖煮，有一定难度但不算复杂，适合有基础烹饪经验的朋友尝试，从备料到出锅大约需要 40 分钟。","tags":["辣","汤"],"ingredients":[{"name":"食用油：10ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜：3 片","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜：3 瓣（切成块）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"鲤鱼：1.2 斤（清理过的）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"娃娃菜：13 片（可以多放一些，一顿就缩小了）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐：5-8 克","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽：3ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽：6ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"桂皮：1 块","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角：3 个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"郫县豆瓣酱：20 克","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"干辣椒：4-6 个（根据个人口味选择）","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"鲤鱼清洗干净，改刀（在鱼身上多划几个伤口，方便入味）","group":""},{"text":"娃娃菜清洗干净放入盘中备用","group":""},{"text":"锅中加油，等油热放入“少盐” “姜” “蒜” “郫县豆瓣酱” “桂皮” “八角” 炒出香味","group":""},{"text":"把鱼放锅里煎（3 分钟）每（30 秒）需要翻面","group":""},{"text":"加入“水”（水量尽量和鱼平齐，可以少一点点） 放入 “生抽” “老抽” “娃娃菜”","group":""},{"text":"大火炖 15-20 分钟，汤汁快干时添加 “盐” 即可出锅","group":""}],"tips":["也可以放一些粉条，粉条先凉水/热水，需要泡软，可以和娃娃菜一起放入"]},
{"id":"qingzhengluyu","name":"清蒸鲈鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/清蒸鲈鱼/清蒸鲈鱼.jpg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"385 大卡","time":"","servings":"1-2人份","description":"清蒸鲈鱼是一道粤式经典蒸菜，鱼肉细嫩爽滑，味道清淡鲜美，能最大程度保留鲈鱼的原汁原味。鲈鱼富含优质蛋白和 DHA，营养丰富且易于消化。这道菜操作简单，对新手非常友好，从备料到出锅大约只需三十分钟。","tags":["蒸"],"ingredients":[{"name":"鲈鱼 一条","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香葱 三根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜  一块","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"蒸鱼豉油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"料酒","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"食用盐","amount":"5-10g","optional":false,"amountValue":10,"amountUnit":"g"}],"steps":[{"text":"姜切片切丝、香葱的葱白切段，葱绿切丝，切丝后放入冷水浸泡备用。","group":""},{"text":"鲈鱼处理好后洗净，用厨房纸擦干，两面分别划几刀，用盐洗掉鱼身的粘液，并用 10g 盐抹遍鱼身的内外，腌制 10 分钟以上。","group":""},{"text":"补充一个鲈鱼改刀和摆盘的方法，改刀后可以让鲈鱼立起来蒸，均匀受热，同时吃起来更加方便，无需翻面。","group":""},{"text":"","group":""},{"text":"","group":""},{"text":"鱼肚内塞上姜和葱白，鱼身也撒上姜和葱白，量为备用的一半。蒸鱼的碟子用筷子将鱼跟碟子隔开蒸","group":""},{"text":"水烧热感觉到水温后放进入鱼","group":""},{"text":"大火清蒸 10 分钟。","group":""},{"text":"蒸好的鱼，用干净的盘子装起来并去除身上姜蒜","group":""},{"text":"鱼身浇上 15ml 蒸鱼豉油","group":""},{"text":"鱼身重新撒上姜和葱丝，锅内加上 10ml 食用油并烧热，将食用油淋至鱼身即可出菜","group":""}],"tips":["技术总结：","这道菜属于有手就行，关键点在于火候，鱼的大小跟火候都会相关，太久会导致鱼肉太老极度影响口感，太短会导致部分鱼肉没熟。所以大火蒸鱼一般是 10 分钟内较佳。","切记蒸鱼需要用筷子隔开装鱼的盘子，这样做的好处有两点：","1、鱼在蒸的过程中会将水滴到盘子，如果鱼直接接触会导致鱼食用时会腥。","2、能够将鱼均匀受热。","这道菜难度系数简单，而且味道非常棒哦"]},
{"id":"qingzhengshenghao","name":"清蒸生蚝","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"184 大卡","time":"","servings":"1人份","description":"清蒸生蚝是一道原汁原味的沿海家常菜，蚝肉鲜嫩多汁，带着淡淡的海水咸香，蒜蓉与姜丝激发出清甜口感。生蚝富含优质蛋白和锌元素，能帮助提升免疫力。操作不算复杂，但掀开滚烫锅盖和处理蚝壳需要稍加小心，新手也能顺利完成。从刷洗到出锅，大约只需二十分钟。","tags":["蒸"],"ingredients":[{"name":"饮用水","amount":"1 升","optional":false,"amountValue":null,"amountUnit":""},{"name":"生蚝","amount":"6 个","optional":false,"amountValue":6,"amountUnit":"个"},{"name":"葱","amount":"3 颗","optional":false,"amountValue":3,"amountUnit":"颗"},{"name":"蒜","amount":"6 瓣","optional":false,"amountValue":6,"amountUnit":"瓣"},{"name":"姜","amount":"1 小块","optional":false,"amountValue":null,"amountUnit":""},{"name":"酱油 每个生蚝","amount":"1 ml","optional":false,"amountValue":1,"amountUnit":"ml"}],"steps":[{"text":"将生蚝用刷子刷干净（没有刷子用牙刷）。","group":""},{"text":"蒸锅中放水，将蒸屉放上之后，将 6 个生蚝平铺在蒸屉，使用 50%功率，蒸 3 分钟。","group":""},{"text":"用右手拿着湿抹布掀开烫锅盖，将每个生蚝的外壳掀开一半去掉，生蚝的凸面向下，平面向上，每个放 1 根姜丝,10g 蒜末放到生蚝上。","group":""},{"text":"关上烫锅盖，100%功率蒸 3.5 分钟。","group":""},{"text":"停火，用右手拿着抹布掀开烫锅盖，每个放 5ml 酱油。","group":""},{"text":"盛盘。","group":""}],"tips":[]},
{"id":"rouxiebao","name":"肉蟹煲","category":"水产","categoryKey":"aquatic","emoji":"🦀","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"2111 大卡","time":"","servings":"1-2人份","description":"这道菜酱香浓郁，蟹肉鲜甜微辣，土豆软糯、年糕 Q 弹，汤汁拌饭格外过瘾，属于一道适合聚餐的硬菜。它富含优质蛋白和多种微量元素，营养丰富。制作有一定难度，需处理活蟹、把控火候和调味比例，对新手略具挑战，预计全程约需 1 小时。","tags":["辣","汤","甜","进阶挑战"],"ingredients":[{"name":"肉蟹","amount":"500 g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"虾","amount":"200 g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"土豆","amount":"450 g","optional":false,"amountValue":450,"amountUnit":"g"},{"name":"年糕","amount":"200 g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"洋葱","amount":"100 g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"大蒜","amount":"20 g（如果放了虾，追加 10 g）","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"生姜","amount":"15 g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"干辣椒","amount":"5 g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"青椒","amount":"30 g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"红椒","amount":"30 g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"蚝油","amount":"20 g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"食用油","amount":"30-50 ml（如果放了虾，追加 10 ml；油炸另需 500 mL）","optional":false,"amountValue":50,"amountUnit":"ml"},{"name":"海鲜酱","amount":"15 g（替代：蚝油 12 g + 白砂糖 3 g）","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"黄豆酱","amount":"15 g（替代：生抽 12 ml + 老抽 2 ml + 白糖 1 g）","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"甜面酱","amount":"10 g（替代：白糖 5.5 g + 生抽 4 ml + 老抽 0.5 ml）","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"番茄酱","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"淀粉","amount":"40 g","optional":false,"amountValue":40,"amountUnit":"g"},{"name":"冰糖","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"鸡精","amount":"3 g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"白胡椒粉","amount":"2 g（如果放了虾，追加 1 g）","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"料酒","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"生抽","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"老抽","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"啤酒","amount":"200 ml（如果放了虾，追加 50-100 ml）","optional":false,"amountValue":200,"amountUnit":"ml"},{"name":"清水","amount":"800 ml（如果放了虾，追加 200 ml）","optional":false,"amountValue":800,"amountUnit":"ml"}],"steps":[{"text":"土豆切块为各边均为 3 cm 的立方体，青/红椒切成边长 4 cm 的菱形片，洋葱切成 3 cm 宽的月牙瓣，年糕切成 1 cm 厚片","group":""},{"text":"螃蟹切成 50-80 g 的块，裹薄淀粉，180 °C 油温炸 1 分钟捞出","group":""},{"text":"锅中放油，蒜姜干辣椒爆香，放所有酱料 + 冰糖小火炒出红油，注意别糊底","group":""},{"text":"加螃蟹、土豆、啤酒和清水，烧开转小火炖 12 分钟","group":""},{"text":"放年糕和青红椒，开大火收汁到汤汁可以附着在物品表面，最后撒白胡椒粉","group":""}],"tips":["建议冷冻 20 分钟让螃蟹昏迷（别冻硬！），或用筷子从口器插入破坏神经","如果使用的是冷冻蟹，完全解冻蟹脚容易掉，并且容易造成肉质流失。建议半解冻后裹粉油炸，并将油炸时间延长至 2 分钟","如果灶具功率较小，食材下油锅后容易迅速降温，建议油温预热到 200 °C，并且分多批次油炸","务必去掉蟹胃（三角包）、蟹腮、蟹心（六角形白片）","裹淀粉的螃蟹下锅前务必擦干，热油遇水容易飞溅","死蟹绝对不能用（买来的就是冷冻的除外，但是解冻后未及时使用的也不行）","不与柿子、浓茶同食","痛风患者慎食","年糕切片后泡冷水，下锅前冲洗不容易粘锅，下锅后放在表面，沉入锅底容易糊锅","要是被螃蟹夹了或者烫伤了，先用冷水冲 15 分钟，严重的话及时就医，如果伤口比较深务必就医"]},
{"id":"shuizhuyu","name":"水煮鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"248 大卡","time":"","servings":"3-5人份","description":"水煮鱼是一道麻辣鲜香、鱼肉嫩滑的经典川菜。巴沙鱼富含优质蛋白且脂肪含量低，搭配时令蔬菜营养均衡。做法中等难度，对新手有一定挑战，但按步骤操作也能成功。预计制作时长约 2 小时。","tags":["辣","进阶挑战"],"ingredients":[{"name":"巴沙鱼","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"蔬菜（比如土豆片/豆芽/花菜/生菜/……） 可有不同搭配，推荐合计重量","amount":"300g 至 500g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"红油豆瓣酱","amount":"40g （不怕辣想多加红油就多加 10 至 20g）","optional":false,"amountValue":40,"amountUnit":"g"},{"name":"豆豉","amount":"10g （可选）","optional":true,"amountValue":10,"amountUnit":"g"},{"name":"藤椒油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"菜籽油","amount":"25ml","optional":false,"amountValue":25,"amountUnit":"ml"},{"name":"白胡椒粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"大蒜","amount":"2 瓣","optional":false,"amountValue":2,"amountUnit":"瓣"},{"name":"盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"糖","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"准备：巴沙鱼若是从冷冻柜里取出，需要放室温自然解冻 5 小时再做切片处理。","group":""},{"text":"切片：巴沙鱼撇成薄片，约 5cm 长，3cm 宽。","group":""},{"text":"[腌制](../../tips/learn/学习腌.md)：将切好片的巴沙鱼放入大不锈钢碗中","group":""},{"text":"加入 30g 豆瓣酱，3g 盐，10ml 藤椒油，3g 白胡椒粉","group":""},{"text":"用手抓匀后加入 5ml 菜籽油收尾封住口味","group":""},{"text":"常温静置至少 30 分钟入味。","group":""},{"text":"备菜：大蒜切成蒜末。以 300g 花菜，200g 生菜为例，将花菜与生菜洗净。","group":""},{"text":"焯水与炒菜：花菜[开水锅焯水](../../tips/learn/学习焯水.md)备用；将生菜洗净晾干，炒熟备用（不用放油）。","group":""},{"text":"炒豆瓣酱：热锅冷油（菜籽油 20ml），加入 10g 豆瓣酱，10g 豆豉（可选），加入蒜末，**中火**慢炒。","group":""},{"text":"汆鱼片：加入 150ml 热水，水很快开后加入腌制好的鱼片，轻轻翻动让鱼片在水中散开，加入 2g 盐和 2g 糖调味（此时可根据个人口味调整盐的用量）。水再次沸腾后即可盛盘。","group":""},{"text":"盛盘：先将熟的蔬菜盛至大碗中，然后将热的鱼片盛在蔬菜上面，浇上锅中剩余热汤即可！","group":""}],"tips":["垫底的蔬菜组合及用量可自由发挥，但需要注意各种蔬菜的特点，比如改成土豆的时候，需要将土豆片/土豆块煮熟（可以用筷子戳一戳确认）。","红油豆瓣酱（辣度）以及盐的用量可根据个人口味调整。","注意切鱼片的时候可以垂直于鱼片长条的方向先剁成 5cm 的鱼块，然后翻转 90 度斜着撇成薄片。","腌制的时候注意不要太用力抓。","How to Fillet a Fish 怎样给鱼剔骨"]},
{"id":"suanrongxia","name":"蒜蓉虾","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/蒜蓉虾/1.jpeg","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"456 大卡","time":"","servings":"1-2人份","description":"这道广东传统名菜以鲜香嫩滑著称，虾肉清甜弹牙，蒜香浓郁扑鼻。海虾富含优质蛋白和钙、硒等微量元素，搭配蒜蓉有助杀菌开胃。做法十分简单，处理虾、铺酱、蒸制、淋油几步即成，新手也能轻松驾驭，全程约需 15 分钟。","tags":["新手友好"],"ingredients":[{"name":"海虾","amount":"8 只","optional":false,"amountValue":8,"amountUnit":"只"},{"name":"蒜蓉酱","amount":"50 g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"食用油","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"生抽","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"用刀从虾头中间切开，切到距离虾尾 1 cm","group":""},{"text":"将蒜蓉酱铺在虾身中间，放在盘子中","group":""},{"text":"锅中倒入热水，将盘子放入锅中，大火蒸 3 分钟","group":""},{"text":"烧热油，倒入虾盘中，倒入生抽","group":""}],"tips":[]},
{"id":"suanxianghuangyouxia","name":"蒜香黄油虾","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/蒜香黄油虾/1.jpg","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"526 大卡","time":"","servings":"1-2人份","description":"蒜香黄油虾是一道经典的西式海鲜菜，虾肉鲜嫩弹牙，被浓郁的蒜香和黄油包裹，带有淡淡柠檬清香。虾肉富含优质蛋白，搭配黄油提供能量，适合快速补充营养。做法简单，只需几种常见食材，新手也能轻松上手，从备料到出锅大约二十分钟。","tags":["新手友好"],"ingredients":[{"name":"大虾","amount":"8-10 只（约 200g）","optional":false,"amountValue":10,"amountUnit":"只"},{"name":"无盐黄油","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"大蒜","amount":"4 瓣（约 20g）","optional":false,"amountValue":4,"amountUnit":"瓣"},{"name":"白葡萄酒","amount":"15ml（可选）","optional":true,"amountValue":15,"amountUnit":"ml"},{"name":"柠檬","amount":"1/4 个","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"橄榄油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"}],"steps":[{"text":"大虾去头去壳留尾，用牙签挑去虾线，洗净后用厨房纸吸干水分","group":""},{"text":"大蒜切成蒜末，备用","group":""},{"text":"中火加热平底锅，放入 10ml 橄榄油","group":""},{"text":"油热后放入大虾，每面煎 1-1.5 分钟至变色，取出备用","group":""},{"text":"同一锅中加入黄油，融化后放入蒜末，小火炒香（约 30 秒）","group":""},{"text":"如使用白葡萄酒，此时加入并煮至酒精挥发（约 1 分钟）","group":""},{"text":"将虾放回锅中，与蒜香黄油酱汁翻炒均匀（约 1 分钟）","group":""},{"text":"挤入柠檬汁，翻炒均匀后立即关火","group":""},{"text":"装盘，淋上锅中剩余酱汁","group":""}],"tips":["虾不宜过度烹饪，否则会变硬"]},
{"id":"tangculiyu","name":"糖醋鲤鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/糖醋鲤鱼/成品.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"1011 大卡","time":"1小时","servings":"1人份","description":"糖醋鲤鱼是经典鲁菜，外酥里嫩、酸甜适口，鱼身炸至金黄浇上红亮糖醋汁，十分诱人。鱼肉富含优质蛋白和多种矿物质，易于消化吸收。这道菜对新手不太友好，难度中等偏上，需掌握改刀、挂糊和油炸火候。从备料到成菜大约需要 1 小时。","tags":["进阶挑战"],"ingredients":[{"name":"鲤鱼","amount":"约 3 斤","optional":false,"amountValue":3,"amountUnit":"斤"},{"name":"清水","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"番茄酱","amount":"40g","optional":false,"amountValue":40,"amountUnit":"g"},{"name":"白糖","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"白醋","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"淀粉","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"盐","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"大葱","amount":"30g（约半颗）","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"姜","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"料酒","amount":"25g","optional":false,"amountValue":25,"amountUnit":"g"}],"steps":[{"text":"将鱼清洗干净，确保无鱼鳞等异物","group":""},{"text":"将鱼头朝左，鱼肚朝下，右手持刀。刀竖直切下 1cm，按紧鱼身往左片 3-4cm，再将鱼片中间轻轻划一刀","group":""},{"text":"将鱼放进盆里，然后将大姜切片，大葱切段（随便切切就行了，主要是需要去腥味）","group":""},{"text":"用吃奶的力气将大葱大姜里的汁水挤到盆中","group":""},{"text":"加入 20g 盐，25g 料酒，然后给鲤鱼搓个澡，涂抹均匀","group":""},{"text":"","group":""},{"text":"找个干净的盆，加入 100g 面粉、200g 淀粉、180g 水、5g 盐，用手将其搅拌均匀，面糊此时粘稠呈可拉丝状态，然后打入一个鸡蛋，再次搅匀","group":""},{"text":"等待 30 分钟","group":""},{"text":"将鱼放在案板上，用干毛巾将鱼身上的水擦干（这样可以更好的挂糊）","group":""},{"text":"将盆冲洗干净，用干毛巾擦干","group":""},{"text":"起锅烧油，加入约 1L 的油，将油温烧至 7 成热，约 200-240 度","group":""},{"text":"捏起鱼的尾巴，将鱼头沉入锅底，用勺子往鱼的身上淋热油，待面糊成型后，将鱼慢慢放入锅中，拿锅铲轻轻铲起鱼的头部，然后垫上笊篱。防止底部炸糊。","group":""},{"text":"准备一个盛鱼的盘子，放在锅的旁边。","group":""},{"text":"用锅铲从鱼身处轻轻铲入，两个工具配合鱼翻个身。再炸两分钟，还是同样的方式（笊篱托着鱼头，锅铲托着鱼身，将鱼盛入盘中）","group":""},{"text":"将锅中的油倒入擦干的盆中，放置一边，然后将锅刷干净","group":""},{"text":"将 50g 清水、40g 番茄酱、20g 白糖、10g 白醋放入小碗中，搅拌均匀","group":""},{"text":"再准备一个小碗加入 10g 淀粉、10g 水，搅拌成水淀粉","group":""},{"text":"开大火将锅烧热，然后倒入之前准备的料汁，大火烧开，转小火","group":""},{"text":"加入调好的水淀粉，边倒边搅拌，然后 20 秒后关火","group":""},{"text":"将熬好的糖醋汁用勺子均匀地浇在鱼身上，可以加点香菜或葱花点缀，糖醋鲤鱼就做好了","group":""},{"text":"","group":""}],"tips":["这道菜难度系数算中等吧，对新手还是不太友好的......"]},
{"id":"weibocongjiangheixueyu","name":"微波葱姜黑鳕鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"749 大卡","time":"","servings":"1人份","description":"微波做鱼，葱姜提鲜，热油一淋，香气四溢，是一道肉质细嫩、滋味咸鲜的家常蒸鱼菜，属于改良粤式做法。黑鳕鱼富含优质蛋白和欧米伽-3 脂肪酸，对心脑健康有益。操作不算复杂，但需掌握火候和油温，更适合有一定下厨经验的朋友。从备料到上桌大约只需二十分钟。","tags":["辣"],"ingredients":[{"name":"黑鳕鱼，带皮，2 片，450g（本菜谱主角，所有调料可根据鳕鱼的实际重量进行比例调整）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"青葱，葱白，25g。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"青葱，葱绿，10g。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜，13g。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒，5mL。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"酱油，25mL。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"芝麻油，2mL。","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"花生油，50mL。","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"鱼片分别放入密封袋，鱼皮向下放在盘子中。","group":""},{"text":"取葱白切丝 25g，姜去皮后切丝，10g，混合在一起后分成两半，分别放在袋内鱼片上。","group":""},{"text":"每个袋子倒入 2.5mL 料酒。","group":""},{"text":"封好密封袋，放入微波炉中，中火（800 瓦）微波至*不透明且容易散开*时（约 3.5-5 分钟），从袋中取出鱼片。","group":""},{"text":"去除青葱和姜。","group":""},{"text":"取酱油 25mL，芝麻油 2mL，混合均匀后平均淋在两片鱼片上。","group":""},{"text":"取葱绿切细丝 10g，姜去皮后切丝 3g，混合后分成两份撒在鱼片上。","group":""},{"text":"取花生油 50mL，在小锅中加热至 190℃。","group":""},{"text":"将热油淋到放油葱绿的鱼片上，立刻上桌。","group":""}],"tips":["| 鱼类     | 是否切片 | 重量 | 微波时间  |","|----------|----------|------|-----------|","| 海鲈鱼   | 整条     | 450g | 6.5 分钟  |","| 罗非鱼   | 整条     | 800g | 6 分钟    |","| 大比目鱼 | 切片     | 170g | 2.25 分钟 |","| 龙脷鱼   | 切片     | 170g | 1.5 分钟  |","如果想让香气更为浓郁，在微波前可将葱姜与料酒均匀涂抹在鱼片的两侧，再进行微波加热。"]},
{"id":"xiangjianqiaozuiyu","name":"香煎翘嘴鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/香煎翘嘴鱼/香煎翘嘴鱼.jpeg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"820 大卡","time":"","servings":"1-2人份","description":"香煎翘嘴鱼是一道风味浓郁的家常河鲜，鱼身经腌晒后干香紧实，煎至外皮金黄酥脆，肉质细腻咸鲜，带着豆瓣与青椒的微辣回甜。鱼肉富含优质蛋白和不饱和脂肪酸，营养易吸收。制作需要提前腌晒两到四天，烹饪时间约半小时，煎鱼时需耐心控火，对新手稍有挑战，但成菜后香气扑鼻，格外下饭。","tags":["辣","进阶挑战"],"ingredients":[{"name":"翘嘴鱼：2 斤最佳","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜沫：20g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"葱：半根（50 克）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜：4 个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香菜：个人口味","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽：2ml（不太喜欢重口的可以不放）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"白糖：10g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"干辣椒：4-6 个（根据个人口味选择）","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒：100ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽：4ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐：约","amount":"50g 用于腌制鱼","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"食用油：100ml","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"鱼开背杀好（让卖鱼的杀好，千万不要剖腹杀鱼，切记是开背），清洗干净","group":""},{"text":"鱼表面用盐涂抹均匀，倒入料酒约 80ml,姜末 20g，放入冰箱保鲜层进行腌制 1-2 天","group":""},{"text":"取出腌制好的鱼，用绳挂起晾晒至半干（约 1-2 天，具体时间需结合气温与阳光）","group":""},{"text":"食用前请将鱼用清水清洗，沥干水分（防止水遇油飞溅）","group":""},{"text":"开大火将锅烧热，迅速改小火，锅中放油，尽量保持整个锅表面有油，将鱼沿锅边划入锅内（先煎鱼背面）","group":""},{"text":"鱼入锅后（和翻面后），不要着急移动鱼的位置（此时容易破皮），煎约 30 秒后，尝试晃动锅","group":""},{"text":"背面煎约 1 分钟后，翻面煎约 1-2 分钟，煎至两面金黄","group":""},{"text":"等两面都煎好时，把鱼推向锅边一点，留点空间放入豆瓣酱炒香味，放入姜蒜，","group":""},{"text":"炒出佐料香味后，加入料酒，生抽，老抽，倒入热水，水量和鱼平齐或者少点","group":""},{"text":"此时改中大火，煮 5-10 分钟，后放入青椒断，白糖，鸡精，十三香，陈醋","group":""},{"text":"改小火 2-5 分钟，放入葱，香菜，即可出锅","group":""}],"tips":["切记鱼是开背杀，腌制时，鱼表面涂抹均匀食盐即可，腌制时间，晾晒时间 1-2 天即可","煎鱼全程小火，刚入锅时不要移动鱼，会破皮","青椒断放入后注意观察熟透程度，里面的青椒很好吃，另外香菜最后放","注意火候的切换，豆瓣酱，白糖的调鲜效果，与陈醋的增香效果"]},
{"id":"xiangyoushansi","name":"响油鳝丝","category":"水产","categoryKey":"aquatic","emoji":"🫗","color":"#7FC8E8","light":"#EAF6FC","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"556 大卡","time":"","servings":"1-2人份","description":"响油鳝丝是一道经典的江浙沪家常菜，鳝丝鲜嫩滑爽，蒜香浓郁，酱汁微甜，淋上热猪油后香气四溢，非常下饭。鳝鱼富含优质蛋白和 DHA，营养丰富。这道菜对刀工和火候有一定要求，难度适中，新手需要稍加练习。从备料到出锅，一般 大约 40 分钟就能端上餐桌。","tags":[],"ingredients":[{"name":"鳝丝","amount":"400 g","optional":false,"amountValue":400,"amountUnit":"g"},{"name":"大蒜","amount":"40 g","optional":false,"amountValue":40,"amountUnit":"g"},{"name":"姜末","amount":"20 g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"料酒","amount":"13 g","optional":false,"amountValue":13,"amountUnit":"g"},{"name":"生抽","amount":"3 g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"蚝油","amount":"2 g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"老抽","amount":"2 g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"食用盐","amount":"2 g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"白糖","amount":"6-15 g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"胡椒粉","amount":"3.5-8 g","optional":false,"amountValue":8,"amountUnit":"g"},{"name":"淀粉","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"水","amount":"50 g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"蒜末","amount":"40 g","optional":false,"amountValue":40,"amountUnit":"g"},{"name":"葱花","amount":"15 g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"猪油","amount":"20 g","optional":false,"amountValue":20,"amountUnit":"g"}],"steps":[{"text":"将鳝鱼切成三段后切成细丝","group":""},{"text":"加入 0.5 g 胡椒粉、3 g 料酒搅拌均匀，再加入 5 g 香油腌制","group":""},{"text":"热油滑锅","group":""},{"text":"加入植物油，烧到 6 成热","group":""},{"text":"加入一半蒜末和全部姜末，翻炒几下","group":""},{"text":"加入鳝丝，中火爆炒 30 秒","group":""},{"text":"边缘淋入 10 g 料酒，翻炒几下","group":""},{"text":"加入生抽，炒匀","group":""},{"text":"加入蚝油、老抽，翻炒几下","group":""},{"text":"加入食用盐、白糖、3 g 胡椒粉，炒匀","group":""},{"text":"淀粉和水混合为水淀粉，倒入锅中，收汁至浓稠","group":""},{"text":"装盘，撒上蒜蓉、葱花","group":""},{"text":"另起锅烧热，加入猪油，烧至七成热，浇在鳝丝上","group":""}],"tips":["不能将鳝鱼的血洗得太干净，否则鳝鱼很容易发黑发臭","鳝鱼可以让摊主帮忙宰杀","可以多加一些胡椒粉和白糖，有利于去腥增香","参考资料：“响油鳝丝”的家常做法，味道很赞，先收藏了 - YouTube"]},
{"id":"xiaolongxia","name":"小龙虾","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/小龙虾/成品.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"571 大卡","time":"45分钟","servings":"1人份","description":"这道菜麻辣鲜香，虾肉细嫩多汁，是经典的川湘风味下酒菜，在家自制干净又实惠。小龙虾富含优质蛋白和多种微量元素，但汤汁含油盐较多，适合偶尔享用。处理活虾和多种香料对新手有一定挑战，不过不去虾线可明显降低难度。从备料到出锅大约需要 45 分钟。","tags":["辣","进阶挑战"],"ingredients":[{"name":"小龙虾","amount":"2 斤","optional":false,"amountValue":2,"amountUnit":"斤"},{"name":"油","amount":"70 毫升（这是平时炒菜 3 倍量）","optional":false,"amountValue":null,"amountUnit":""},{"name":"香叶","amount":"两片","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角","amount":"一个","optional":false,"amountValue":null,"amountUnit":""},{"name":"桂皮","amount":"3 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"青花椒","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"花椒","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"子弹头辣椒","amount":"5 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"葱","amount":"一根大葱","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜","amount":"30 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜","amount":"7 瓣大蒜","optional":false,"amountValue":7,"amountUnit":"瓣"},{"name":"郫县豆瓣","amount":"30 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"黄豆酱","amount":"30 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"啤酒","amount":"500 毫升","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽","amount":"30 毫升","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"小龙虾刷干净去虾线，葱切 2cm 葱段，姜蒜切末。","group":""},{"text":"烧油，油微热, 下香叶、八角、桂皮、青花椒、花椒、子弹头辣椒。","group":""},{"text":"香料出香气之后下锅葱姜蒜","group":""},{"text":"葱姜蒜爆香后，加入郫县豆瓣、黄豆酱，炒出红油。","group":""},{"text":"下小龙虾，翻炒至变色。","group":""},{"text":"加入啤酒，等啤酒烧开后加入生抽，盐。","group":""},{"text":"将小龙虾完全煮熟后出锅。","group":""}],"tips":["饭店应该都是油炸一遍，家庭油炸的话，太浪费了，所以在这个菜谱里用油比炒菜油多一些煎一下，实测同样好吃。","去虾线后的虾肉比不去虾线的虾肉口感差一些，并且小龙虾去虾线对新手是一个挑战，能接受虾线的情况下不去虾线也可以。"]},
{"id":"yangshuopijiuyu","name":"阳朔啤酒鱼","category":"水产","categoryKey":"aquatic","emoji":"🐟","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/阳朔啤酒鱼/阳朔啤酒鱼.png","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"1092 大卡","time":"","servings":"1-2人份","description":"阳朔啤酒鱼是广西阳朔的地方名菜，选用漓江鲜鱼带鳞煎制，以啤酒代水焖煮，鱼鳞酥脆、鱼肉鲜嫩，啤酒香与番茄微酸交融，风味浓郁独特。鱼肉富含优质蛋白和矿物质，搭配番茄、辣椒，维生素丰富且开胃助食。制作难度中等，对新手稍具挑战，但跟着步骤操作也能成功，预计 30 分钟即可完成。","tags":["辣"],"ingredients":[{"name":"剑骨鱼或鲤鱼","amount":"1 条（约 750g，不去鳞）","optional":false,"amountValue":1,"amountUnit":"条"},{"name":"料酒","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"漓泉啤酒","amount":"330ml（1 瓶）","optional":false,"amountValue":330,"amountUnit":"ml"},{"name":"番茄","amount":"2 个（约 300g）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"青椒","amount":"2 个（约 150g）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"红椒","amount":"1 个（约 80g）","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"大蒜","amount":"6 瓣（约 30g）","optional":false,"amountValue":6,"amountUnit":"瓣"},{"name":"生姜","amount":"1 块（约 20g）","optional":false,"amountValue":1,"amountUnit":"块"},{"name":"葱","amount":"2 根（约 40g）","optional":false,"amountValue":2,"amountUnit":"根"},{"name":"桂林辣椒酱","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"生抽","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"老抽","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"白糖","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"食盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"食用油","amount":"30ml","optional":false,"amountValue":30,"amountUnit":"ml"}],"steps":[{"text":"鱼处理好内脏，保留鱼鳞，清洗干净，从腹部剖开成两半（背部相连），用 15ml 料酒、姜片、食盐 3g 腌制 15 分钟","group":""},{"text":"番茄切块，青椒红椒切块，大蒜拍碎，生姜切片，葱切段（葱白葱叶分开）","group":""},{"text":"用姜片擦拭锅底，热锅后倒入 30ml 食用油，油热后放入鱼（鱼皮朝下），煎至两面金黄、鱼鳞酥脆，盛出备用","group":""},{"text":"锅中留底油，放入葱白、姜片、蒜瓣爆香","group":""},{"text":"加入 15g 桂林辣椒酱，炒出红油","group":""},{"text":"放入番茄块，翻炒至番茄出汁变软","group":""},{"text":"倒入整瓶啤酒，加入 15ml 生抽、5ml 老抽、5g 白糖、5g 食盐，搅拌均匀","group":""},{"text":"放入煎好的鱼，大火烧开后转中小火，盖上锅盖焖煮 15-20 分钟","group":""},{"text":"开盖，放入青椒红椒块，继续煮 3-5 分钟","group":""},{"text":"大火收汁至汤汁浓稠，撒上葱叶段，出锅装盘","group":""}],"tips":["鱼鳞是这道菜的关键特色，一定要保留，煎炸后会变得酥脆可口","鱼剖成两半更容易煎透入味，比整条划刀效果更好","正宗做法使用桂林辣椒酱（非郫县豆瓣酱），搭配漓泉啤酒，没有桂林辣椒酱可以用蒜蓉辣酱代替","番茄要炒软出汁，这样汤汁更浓郁","汤汁不要收太干，留一些拌饭或拌面非常好吃","参考资料：阳朔啤酒鱼的做法"]},
{"id":"youmendaxia","name":"油焖大虾","category":"水产","categoryKey":"aquatic","emoji":"🦐","color":"#7FC8E8","light":"#EAF6FC","image":"dishes/aquatic/油焖大虾/油焖大虾.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"584 大卡","time":"40分钟","servings":"1人份","description":"这道鲁菜经典以咸甜交融的酱汁包裹整虾，成菜红亮油润，虾肉紧实弹嫩。虾本身富含优质蛋白与虾青素，脂肪含量低，是补充营养又不易增加负担的食材。制作时需要炼葱油、剪虾、焖烧、收汁，对火候和调味把握有一定要求，更适合有基础的厨友尝试，全程大约需要 40 分钟。","tags":["辣","进阶挑战"],"ingredients":[{"name":"虾","amount":"10 只","optional":false,"amountValue":10,"amountUnit":"只"},{"name":"花椒","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"葱","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"姜","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"黄酒","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"冰糖","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"植物油","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"剪虾枪到根上，虾须虾爪都剪掉，沙包挑掉，开背虾线挑出来，洗净备用","group":""},{"text":"炸料油","group":""},{"text":"油温三成热放花椒，油热离火，放葱姜（不要让油变色最好）葱稍微变黄沥油 （葱油弄多了可以留着作为拌面使用）。","group":""},{"text":"下油，虾摆放整齐，两面变色后轻轻摁虾头","group":""},{"text":"放姜米（姜切成细颗粒）","group":""},{"text":"黄酒 30g","group":""},{"text":"水两小碗","group":""},{"text":"盐 3g","group":""},{"text":"冰糖 10 克","group":""},{"text":"大火烧开转小火盖盖子闷（中途不能再加汤水，不要开盖）","group":""},{"text":"皮亮虾弯就可以起锅，虾摆盘","group":""},{"text":"收汁（过滤后倒回锅里收浓，放葱油 ） 汤汁剩余 1/4 时。","group":""},{"text":"浇汁","group":""},{"text":"完成","group":""},{"text":"","group":""},{"text":"开吃✅","group":""}],"tips":["做法参考：B 站老饭骨视频从小吃到大的油焖大虾居然是假的？泰斗级大师还原真·味道"]}
];
